import unittest
from similarity import jaccard_stable_selection as core
from similarity import jaccard_stable_selection_api as api

class OrdinaryTests(unittest.TestCase):
    def test_ordinary_0(self):
        self.assertEqual(core.jaccard_score([],[]),1.0)

    def test_ordinary_1(self):
        self.assertEqual(core.jaccard_score(["a"],["a"]),1.0)

    def test_ordinary_2(self):
        self.assertEqual(core.jaccard_score(["a"],["b"]),0.0)

    def test_ordinary_3(self):
        self.assertIsNone(api.most_similar([],[]))

    def test_ordinary_4(self):
        self.assertEqual(api.most_similar([["a"]],["a"]),0)
